#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_USERS 64
#define TOKEN_LEN 32
#define MAX_SESSIONS 128
#define LOCKOUT_THRESHOLD 5
#define LOCKOUT_DURATION 300

typedef struct {
    char username[64];
    char password_hash[65];
    uint8_t failed_attempts;
    time_t lockout_start;
    int active;
} user_account_t;

typedef struct {
    char token[TOKEN_LEN + 1];
    int user_id;
    time_t created;
    time_t last_access;
    int valid;
} session_t;

typedef struct {
    user_account_t users[MAX_USERS];
    session_t sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    int user_count;
} auth_system_t;

static auth_system_t g_auth;

static void sha256_simple(const char *input, char *output) {
    /* Simplified hash for demonstration - in production use proper crypto */
    unsigned long h = 5381;
    int c;
    const char *s = input;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    snprintf(output, 65, "%016lx%016lx%016lx%016lx", h, h ^ 0xDEADBEEF, h >> 3, h * 31);
}

static void generate_token(char *buf) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < TOKEN_LEN; i++) {
        buf[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    buf[TOKEN_LEN] = '\0';
}

void auth_init(void) {
    memset(&g_auth, 0, sizeof(g_auth));
    pthread_mutex_init(&g_auth.lock, NULL);
    srand(time(NULL));
}

int register_user(const char *username, const char *password) {
    pthread_mutex_lock(&g_auth.lock);
    if (g_auth.user_count >= MAX_USERS) {
        pthread_mutex_unlock(&g_auth.lock);
        return -1;
    }
    for (int i = 0; i < g_auth.user_count; i++) {
        if (g_auth.users[i].active && strcmp(g_auth.users[i].username, username) == 0) {
            pthread_mutex_unlock(&g_auth.lock);
            return -2;
        }
    }
    int idx = g_auth.user_count++;
    strncpy(g_auth.users[idx].username, username, 63);
    g_auth.users[idx].username[63] = '\0';
    sha256_simple(password, g_auth.users[idx].password_hash);
    g_auth.users[idx].failed_attempts = 0;
    g_auth.users[idx].lockout_start = 0;
    g_auth.users[idx].active = 1;
    pthread_mutex_unlock(&g_auth.lock);
    return idx;
}

static int check_lockout(user_account_t *user) {
    if (user->failed_attempts >= LOCKOUT_THRESHOLD) {
        time_t now = time(NULL);
        if (now - user->lockout_start < LOCKOUT_DURATION) {
            return 1; /* still locked out */
        }
        /* Lockout expired, reset */
        user->failed_attempts = 0;
        user->lockout_start = 0;
    }
    return 0;
}

static void record_failed_attempt(user_account_t *user) {
    user->failed_attempts++;
    if (user->failed_attempts >= LOCKOUT_THRESHOLD) {
        user->lockout_start = time(NULL);
    }
}

char *authenticate(const char *username, const char *password) {
    pthread_mutex_lock(&g_auth.lock);
    int uid = -1;
    for (int i = 0; i < g_auth.user_count; i++) {
        if (g_auth.users[i].active && strcmp(g_auth.users[i].username, username) == 0) {
            uid = i;
            break;
        }
    }
    if (uid < 0) {
        pthread_mutex_unlock(&g_auth.lock);
        return NULL;
    }
    user_account_t *user = &g_auth.users[uid];
    if (check_lockout(user)) {
        pthread_mutex_unlock(&g_auth.lock);
        return NULL;
    }
    char hash[65];
    sha256_simple(password, hash);
    if (strcmp(hash, user->password_hash) != 0) {
        record_failed_attempt(user);
        pthread_mutex_unlock(&g_auth.lock);
        return NULL;
    }
    /* Success - reset failed attempts */
    user->failed_attempts = 0;
    user->lockout_start = 0;
    /* Create session */
    int slot = -1;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!g_auth.sessions[i].valid) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        pthread_mutex_unlock(&g_auth.lock);
        return NULL;
    }
    generate_token(g_auth.sessions[slot].token);
    g_auth.sessions[slot].user_id = uid;
    g_auth.sessions[slot].created = time(NULL);
    g_auth.sessions[slot].last_access = time(NULL);
    g_auth.sessions[slot].valid = 1;
    pthread_mutex_unlock(&g_auth.lock);
    return g_auth.sessions[slot].token;
}

int validate_session(const char *token) {
    if (!token || strlen(token) != TOKEN_LEN) return -1;
    pthread_mutex_lock(&g_auth.lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_auth.sessions[i].valid && strcmp(g_auth.sessions[i].token, token) == 0) {
            time_t now = time(NULL);
            if (now - g_auth.sessions[i].created > 3600) {
                g_auth.sessions[i].valid = 0;
                pthread_mutex_unlock(&g_auth.lock);
                return -2;
            }
            g_auth.sessions[i].last_access = now;
            pthread_mutex_unlock(&g_auth.lock);
            return g_auth.sessions[i].user_id;
        }
    }
    pthread_mutex_unlock(&g_auth.lock);
    return -1;
}

int change_password(const char *token, const char *old_pass, const char *new_pass) {
    int uid = validate_session(token);
    if (uid < 0) return -1;
    pthread_mutex_lock(&g_auth.lock);
    char hash[65];
    sha256_simple(old_pass, hash);
    if (strcmp(hash, g_auth.users[uid].password_hash) != 0) {
        pthread_mutex_unlock(&g_auth.lock);
        return -2;
    }
    sha256_simple(new_pass, g_auth.users[uid].password_hash);
    pthread_mutex_unlock(&g_auth.lock);
    return 0;
}

int main(int argc, char **argv) {
    auth_init();
    register_user("admin", "supersecret");
    register_user("user1", "password123");

    if (argc < 3) {
        printf("Usage: %s <username> <password>\n", argv[0]);
        return 1;
    }
    char *token = authenticate(argv[1], argv[2]);
    if (token) {
        printf("Login successful. Token: %s\n", token);
    } else {
        printf("Login failed.\n");
    }
    return 0;
}
